import * as THREE from 'three';
const geo={box:new THREE.BoxGeometry(1,1,1),ball:new THREE.SphereGeometry(1,12,8),cyl:new THREE.CylinderGeometry(1,1,1,12)},mat={steel:new THREE.MeshStandardMaterial({color:0x768b91,roughness:.65}),dark:new THREE.MeshStandardMaterial({color:0x263e45}),gold:new THREE.MeshStandardMaterial({color:0xf1bc56}),blue:new THREE.MeshStandardMaterial({color:0x60c7e1,metalness:.3,roughness:.3}),red:new THREE.MeshStandardMaterial({color:0xd77957})};
function mesh(g,type,color,p,s,rx=0){let m=new THREE.Mesh(geo[type],mat[color]);m.position.set(...p);m.scale.set(...s);m.rotation.x=rx;m.castShadow=true;g.add(m);return m;}
export function specialModel(kind){let g=new THREE.Group();g.name=kind;if(kind==='mech'){let legs=[];for(let x of [-.8,.8]){let leg=new THREE.Group();leg.position.set(x,2.2,0);mesh(leg,'box','steel',[0,-.65,0],[.7,1.6,.8]);mesh(leg,'ball','gold',[0,-.1,-.15],[.45,.45,.45]);mesh(leg,'box','dark',[0,-1.6,-.35],[1.05,.55,1.6]);g.add(leg);legs.push(leg);}mesh(g,'box','steel',[0,3.2,0],[2.5,2,1.6]);mesh(g,'box','gold',[0,3.8,-.85],[1.8,.55,.15]);mesh(g,'box','dark',[0,2.3,0],[1.5,.4,1.3]);mesh(g,'box','blue',[0,3.1,-.86],[1.35,.9,.12]);for(let x of [-1.7,1.7]){mesh(g,'ball','gold',[x,3.7,0],[.65,.65,.65]);mesh(g,'box','steel',[x,2.8,-.2],[.7,1.5,.8]);mesh(g,'cyl','dark',[x,2.6,-1],[.25,1.6,.25],Math.PI/2);}mesh(g,'box','dark',[0,4.4,.3],[1.3,.45,1.2]);g.userData.legs=legs;}else if(kind==='helicopter'){mesh(g,'ball','steel',[0,1,0],[1.25,.9,2.1]);mesh(g,'ball','blue',[0,1,-1.25],[1.05,.75,1.15]);mesh(g,'box','gold',[0,1.1,2.6],[.35,.4,3.2]);mesh(g,'box','steel',[0,1.7,4.05],[.25,1.6,.9]);for(let x of [-1.1,1.1]){mesh(g,'box','dark',[x,-.05,0],[.12,.12,3.3]);mesh(g,'box','steel',[x,.4,-.5],[.1,.85,.1]);mesh(g,'box','steel',[x,.4,.7],[.1,.85,.1]);mesh(g,'cyl','dark',[x,.7,-1.5],[.12,1.4,.12],Math.PI/2);}mesh(g,'cyl','dark',[0,2,0],[.15,1,.15]);let rotor=new THREE.Group();rotor.position.y=2.5;mesh(rotor,'box','dark',[0,0,0],[8,.08,.28]);mesh(rotor,'box','dark',[0,.02,0],[.28,.08,8]);g.add(rotor);g.userData.rotor=rotor;let tail=new THREE.Group();tail.position.set(.3,1.6,4);mesh(tail,'box','dark',[0,0,0],[.08,2.1,.16]);mesh(tail,'box','dark',[0,0,0],[.08,.16,2.1]);g.add(tail);g.userData.tailRotor=tail;}else{mesh(g,'box','steel',[0,1.4,0],[2.8,2.8,2.8]);for(let y of [.2,2.6])mesh(g,'box','gold',[0,y,0],[3,.28,3]);for(let x of [-1.3,1.3])mesh(g,'box','gold',[x,1.4,0],[.22,2.8,2.9]);mesh(g,'box','dark',[0,1.5,-1.43],[1.3,1.2,.06]);mesh(g,'box','gold',[0,1.5,-1.48],[.3,.9,.06]);}return g;}
